'use strict';

// MODULES //

var Ajv = require( 'ajv' );
var draft4 = require( 'ajv/lib/refs/json-schema-draft-04.json' );
var schema = require( './nbformat.v4.5.schema.json' );


// VARIABLES //

var ajv = new Ajv({
	'allErrors': true,
	'logger': false,
	'schemaId': 'id'
});
ajv.addMetaSchema( draft4 );
var validateSchema = ajv.compile( schema ); // eslint-disable-line vars-on-top


// MAIN //

/**
* Validates a Jupyter notebook and cell ID uniqueness.
*
* @param {Object} notebook - notebook
* @returns {boolean} boolean indicating whether the notebook is valid
*/
function validate( notebook ) {
	var occupied;
	var errors;
	var id;
	var i;

	if ( !validateSchema( notebook ) ) {
		validate.errors = validateSchema.errors;
		return false;
	}
	occupied = Object.create( null );
	errors = [];
	for ( i = 0; i < notebook.cells.length; i++ ) {
		id = notebook.cells[ i ].id;
		if ( occupied[ id ] ) {
			errors.push({
				'keyword': 'uniqueCellId',
				'dataPath': '.cells['+i+'].id',
				'params': {
					'id': id
				},
				'message': 'must be unique within the notebook'
			});
		}
		occupied[ id ] = true;
	}
	validate.errors = ( errors.length ) ? errors : null;
	return errors.length === 0;
}

validate.errors = null;


// EXPORTS //

module.exports = validate;
